templates.template:
/* =============================================================================
   Storm — a XenForo 2.3 port of the ProBoards "Storm" skin by Allan of Skins n Things.
   Dark textured page, a slate frame, a lightning-over-wheat banner, olive links and glowing category bars.
   The skin's images are embedded below, so the style needs no uploads.
   ============================================================================= */
:root
{
	color-scheme: dark;
}
html
{
	background: url("data:image/png;base64,") repeat #373a2d;
}

body,
.p-pageWrapper
{
	background: transparent;
}

// ---- The 800px framed column -------------------------------------------------------

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 800px;
}

.p-header,
.p-nav,
.p-sectionLinks,
.p-body
{
	background: transparent;
	border: none;
}

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner
{
	background: url("data:image/png;base64,") center top / 800px 26px repeat-y;
	padding-left: 25px;
	padding-right: 25px;
}

.p-header
{
	padding-top: 12px;

	&::before
	{
		content: '';
		display: block;
		max-width: 800px;
		height: 26px;
		margin: 0 auto;
		background: url("data:image/png;base64,") center top / 800px 26px no-repeat;
	}
}

.p-header-content
{
	justify-content: center;
	padding: 4px 0 8px;
}

// The skin's banner replaces the logo. Delete this section to use the logo from Style properties.
.p-header-logo
{
	margin: 0 auto;

	img
	{
		display: none;
	}

	a
	{
		display: block;
		width: 750px;
		max-width: 100%;
		aspect-ratio: 750 / 125;
		background: url("data:image/jpeg;base64,") center / contain no-repeat;
	}
}

.p-navSticky,
.p-navSticky.is-sticky
{
	position: static !important;
}

// ---- Menu bar ---------------------------------------------------------------------------

.p-nav
{
	color: #d7d0c2;
}

.p-nav-inner
{
	background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAaCAIAAAABhlpxAAAAB3RJTUUH2gkBEh4oNItwxgAAAAlwSFlzAAAewgAAHsIBbtB1PgAAAARnQU1BAACxjwv8YQUAAAApSURBVHjaY5RXlmfADVgYmZjwSTMxMlKimwm/bkaKdA9bl4+GGr1dDgCLvgE8A97i8AAAAABJRU5ErkJggg==") left top / auto 100% repeat-x content-box, url("data:image/png;base64,") center top / 800px 26px repeat-y;
}

.p-nav-list
{
	justify-content: center;
	width: 100%;

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #d7d0c2;
		font-size: 11px;
		font-weight: 700;
		letter-spacing: 1px;
		text-transform: uppercase;
		text-shadow: 0 1px 1px #000;

		&:hover
		{
			color: #fdfc75;
			text-decoration: none;
		}
	}

	.p-navEl.is-selected
	{
		background: rgba(255, 255, 255, .14);

		.p-navEl-link
		{
			color: #fdfc75;
		}
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #d7d0c2;

	&:hover
	{
		background: rgba(255, 255, 255, .14);
		color: #fdfc75;
		text-decoration: none;
	}
}

.p-sectionLinks-inner a,
.p-breadcrumbs a
{
	color: #a5a653;
}

.p-body-inner
{
	color: #819183;
	padding-bottom: 16px;
}

.p-title-value,
.p-breadcrumbs
{
	color: #819183;
}

// ---- Blocks: the skin's category head, middle and base images around every block --------

.block-container
{
	background: url("data:image/png;base64,") center top / 100% 12px repeat-y;
	border: none;
	border-radius: 0;
	padding: 0 1%;

	&::before,
	&::after
	{
		content: '';
		display: block;
		height: 12px;
		margin: 0 -1%;
		background: url("data:image/png;base64,") center top / 100% 12px no-repeat;
	}

	&::after
	{
		height: 12px;
		background: url("data:image/png;base64,") center top / 100% 12px no-repeat;
	}
}

.block-body,
.block-row
{
	background: #1f231f;
	color: #8f9f91;
}

.block-header,
.block-minorHeader,
.block-tabHeader,
.menu-header,
.menu-tabHeader,
.block-filterBar,
.dataList-row--header .dataList-cell
{
	background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAaCAIAAAABhlpxAAAAB3RJTUUH2gkBEh4oNItwxgAAAAlwSFlzAAAewgAAHsIBbtB1PgAAAARnQU1BAACxjwv8YQUAAAApSURBVHjaY5RXlmfADVgYmZjwSTMxMlKimwm/bkaKdA9bl4+GGr1dDgCLvgE8A97i8AAAAABJRU5ErkJggg==") left top / auto 100% repeat-x, #313731;
	border-bottom: 1px solid #444d45;
	color: #d7d0c2;
	font-weight: 700;
	text-shadow: none;

	a,
	a:hover
	{
		color: #d7d0c2;
	}

	.block-desc
	{
		color: #d7d0c2;
		opacity: .8;
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: #d7d0c2;
	opacity: .75;

	&:hover,
	&.is-active
	{
		opacity: 1;
		border-color: #d7d0c2;
	}
}

.block-footer
{
	background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAaCAIAAAABhlpxAAAAB3RJTUUH2gkBEh4oNItwxgAAAAlwSFlzAAAewgAAHsIBbtB1PgAAAARnQU1BAACxjwv8YQUAAAApSURBVHjaY5RXlmfADVgYmZjwSTMxMlKimwm/bkaKdA9bl4+GGr1dDgCLvgE8A97i8AAAAABJRU5ErkJggg==") left top / auto 100% repeat-x, #313731;
	border-top: 1px solid #444d45;
	color: #d7d0c2;

	a
	{
		color: #d7d0c2;
	}
}

.node + .node
{
	border-top: 1px solid #444d45;
}

.node-body,
.structItem
{
	background: #1f231f;
}

.structItem
{
	border-top-color: #444d45;
}

.node-title a,
.structItem-title a
{
	color: #a5a653;
	font-weight: 700;

	&:hover
	{
		color: #c4c56a;
	}
}

.node-description,
.node-meta,
.node-stats,
.structItem-minor
{
	color: #8f9f91;
}

// Forum icons: the skin's new-posts image when there's something unread, otherwise no-new-posts.
.node--forum .node-icon i
{
	display: block;
	width: 30px;
	height: 30px;
	margin: 0 auto;
	background: url("data:image/png;base64,") center / contain no-repeat;

	svg,
	&::before
	{
		display: none;
	}
}

.node--forum.node--unread .node-icon i
{
	background-image: url("data:image/png;base64,");
}

.node--link,
.node--page,
.node--category
{
	.node-icon i
	{
		color: #a5a653;
	}
}

.message,
.message-inner
{
	background: #1f231f;
	border-color: #444d45;
}

.message-cell--user
{
	background: #222622;
	border-right-color: #444d45;
}

.message-userArrow::after
{
	border-right-color: #1f231f;
}

.button.button--primary,
a.button.button--primary
{
	background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAaCAIAAAABhlpxAAAAB3RJTUUH2gkBEh4oNItwxgAAAAlwSFlzAAAewgAAHsIBbtB1PgAAAARnQU1BAACxjwv8YQUAAAApSURBVHjaY5RXlmfADVgYmZjwSTMxMlKimwm/bkaKdA9bl4+GGr1dDgCLvgE8A97i8AAAAABJRU5ErkJggg==") left top / auto 100% repeat-x;
	background-color: #3a413a;
	border: 1px solid #444d45;
	color: #d7d0c2;

	&:hover
	{
		color: #fdfc75;
		filter: brightness(1.1);
	}
}

.input
{
	background: #222622;
	border-color: #444d45;
	color: #8f9f91;
}

.menu-content,
.overlay
{
	background: #1f231f;
	border: 1px solid #444d45;
	color: #8f9f91;
}

// ---- Footer: the frame's base, then the skin credit on the page ---------------------------

.p-footer
{
	background: transparent;
	color: #b5b09a;

	&::before
	{
		content: '';
		display: block;
		max-width: 800px;
		height: 26px;
		margin: 0 auto;
		background: url("data:image/png;base64,") center top / 800px 26px no-repeat;
	}

	a
	{
		color: #a5a653;
	}
}

// ---- Narrower than the frame: plain column, scaled banner ------------------------------

@media (max-width: 819px)
{
	.p-header
	{
		padding-top: 0;

		&::before
		{
			content: none;
		}
	}

	.p-header-inner,
	.p-nav-inner,
	.p-sectionLinks-inner,
	.p-body-inner
	{
		background: #1f231f;
		padding-left: 8px;
		padding-right: 8px;
	}

	.p-nav-inner
	{
		background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAoAAAAaCAIAAAABhlpxAAAAB3RJTUUH2gkBEh4oNItwxgAAAAlwSFlzAAAewgAAHsIBbtB1PgAAAARnQU1BAACxjwv8YQUAAAApSURBVHjaY5RXlmfADVgYmZjwSTMxMlKimwm/bkaKdA9bl4+GGr1dDgCLvgE8A97i8AAAAABJRU5ErkJggg==") left top / auto 100% repeat-x;
	}

	.p-footer::before
	{
		background-size: 100% auto;
	}
}
